with a as(select * from public.authors where open_library_id=any(array['OL27363A','OL34184A','OL22019A','OL7634169A','OL13115196A','OL29466A','OL1608524A']::text[])),w as(select * from public.works where open_library_id=any(array['OL20153160W','OL274539W','OL36500932W','OL134875W','OL45867W','OL27962072W','OL6224977W']::text[])) select jsonb_build_object('checked_at',clock_timestamp(),'project','hlvujbrmfdlrfxdjwsmb','authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'works',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from w t),'editions',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where work_id in(select id from w) or isbn_13=any(array['9789463821513','9781405937184','9780140157505','9789493304239','9789032504403','9789029035729','9789029549776','9789461060037','9789029015837']::text[]) or open_library_edition_id=any(array['OL37752967M','OL28701203M','OL12802602M','OL9303640M','OL49336992M','OL33028327M','OL33892403M','OL47082597M','OL27874934M']::text[])),'reserved_range',jsonb_build_object('works',(select count(*) from public.works where id between 987122001 and 987122999),'editions',(select count(*) from public.editions where id between 987222001 and 987222999),'authors',(select count(*) from public.authors where id between 987322001 and 987322999))) as preflight;
